//! Typesetting with Typst.
//!
//! [`Typesetter`] owns an in-memory Typst world with three files:
//! `main.typ` (generated by `absatz_core::codegen`), `template.typ` and
//! `styles.json` (from the active style set). Updates are incremental:
//! Typst's memoization (comemo) reuses everything that did not change.

pub mod bench;
mod world;

use absatz_core::styles::StyleSetSource;
use typst_layout::PagedDocument;

use world::AbsatzWorld;

pub struct Typesetter {
    world: AbsatzWorld,
    document: Option<PagedDocument>,
    /// Inputs changed since the last compile.
    dirty: bool,
}

impl Typesetter {
    pub fn new(style_set: &StyleSetSource) -> Self {
        Self {
            world: AbsatzWorld::new(style_set),
            document: None,
            dirty: true,
        }
    }

    /// Replace the generated document source. Typst diffs it internally,
    /// so only the changed region is reparsed.
    pub fn set_source(&mut self, source: &str) {
        self.dirty |= self.world.set_main(source);
    }

    /// Replace the style tokens (`styles.json`).
    pub fn set_styles(&mut self, styles_json: String) {
        self.dirty |= self.world.set_styles(styles_json);
    }

    /// Compiles if inputs changed; otherwise returns the last document.
    ///
    /// Skipping is not only faster: an unchanged compile is a pure top-level
    /// cache hit, after which `evict(1)` would drop all fine-grained layout
    /// entries and the next real edit would relayout everything (measured:
    /// 1.7 s instead of 70 ms on 100 pages).
    pub fn compile(&mut self) -> Result<&PagedDocument, String> {
        if self.dirty || self.document.is_none() {
            let result = typst::compile::<PagedDocument>(&self.world).output;
            // Keep only what the last compilation used. Measured on 100 pages
            // in Chromium: 292 MB instead of 947 MB with evict(10), typing
            // unchanged. Wasm memory never shrinks, so the peak is what counts.
            comemo::evict(1);
            let document = result.map_err(|errors| {
                let messages: Vec<_> = errors.iter().map(|e| e.message.to_string()).collect();
                messages.join("\n")
            })?;
            self.document = Some(document);
            self.dirty = false;
        }
        Ok(self.document.as_ref().expect("compiled above"))
    }

    pub fn page_count(&self) -> usize {
        self.document.as_ref().map_or(0, |d| d.pages().len())
    }

    pub fn page_svg(&self, index: usize) -> Option<String> {
        let page = self.document.as_ref()?.pages().get(index)?;
        Some(typst_svg::svg(page, &Default::default()))
    }

    /// Raster image of a page as RGBA (width, height, pixels).
    pub fn page_rgba(&self, index: usize, pixel_per_pt: f64) -> Option<(u32, u32, Vec<u8>)> {
        let page = self.document.as_ref()?.pages().get(index)?;
        let options = typst_render::RenderOptions {
            pixel_per_pt: pixel_per_pt.into(),
            ..Default::default()
        };
        let pixmap = typst_render::render(page, &options);
        Some((pixmap.width(), pixmap.height(), pixmap.take()))
    }

    pub fn pdf(&self) -> Result<Vec<u8>, String> {
        let document = self.document.as_ref().ok_or("nothing compiled yet")?;
        typst_pdf::pdf(document, &Default::default())
            .map_err(|errors| format!("{} PDF error(s)", errors.len()))
    }
}

/// Current memory use in MB: wasm linear memory, or peak RSS natively.
pub fn memory_mb() -> f64 {
    #[cfg(target_arch = "wasm32")]
    {
        (core::arch::wasm32::memory_size::<0>() * 65536) as f64 / 1_048_576.0
    }
    #[cfg(not(target_arch = "wasm32"))]
    {
        std::fs::read_to_string("/proc/self/status")
            .ok()
            .and_then(|s| {
                let line = s.lines().find(|l| l.starts_with("VmHWM:"))?;
                line.split_whitespace().nth(1)?.parse::<f64>().ok()
            })
            .map_or(0.0, |kb| kb / 1024.0)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use absatz_core::model::{Block, Document};
    use absatz_core::{codegen, styles};

    #[test]
    fn compiles_small_document() {
        let doc = Document {
            blocks: vec![
                Block::para("h1", "Titel"),
                Block::para("body", "Ein \"Absatz\" mit #Sonderzeichen $ und *Sternen*."),
                Block::para("list", "Punkt eins"),
                Block::para("list", "Punkt zwei"),
                Block::para("quote", "Ein Zitat."),
                Block::para("note", "Ein Hinweis."),
            ],
        };
        let mut ts = Typesetter::new(&styles::STANDARD);
        ts.set_source(&codegen::typst(&doc).source);
        ts.compile().expect("compiles");
        assert_eq!(ts.page_count(), 1);
        assert!(ts.page_svg(0).unwrap().contains("<svg"));
        assert!(ts.pdf().unwrap().starts_with(b"%PDF"));
    }
}
